contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val, address _log) public payable {
        // Make the deciding call: Initialized on a fresh contract.
        bool reverted1;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }

        // Second call should also succeed (no revert guard on Initialized).
        bool reverted2;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }

        // After initialization, SetMinSum and SetLogFile should revert.
        bool setMinSumReverted;
        c.SetMinSum(_val); bool __rev2 = __ESBMC_reverted(); if (__rev2) { setMinSumReverted = true; } else { setMinSumReverted = false; }

        bool setLogFileReverted;
        c.SetLogFile(_log); bool __rev3 = __ESBMC_reverted(); if (__rev3) { setLogFileReverted = true; } else { setLogFileReverted = false; }

        // General rule: Initialized() never reverts; once called, other initialization setters revert.
        assert(!reverted1 && !reverted2 && setMinSumReverted && setLogFileReverted);
    }
}

